INSERT INTO club_texts (club_id, text_type, content) VALUES ((SELECT id FROM clubs WHERE club_number=6101), 'QUOTE_DISCLAIMER', 'Los precios están sujetos a cambio sin previo aviso. Las existencias dependen de las ventas diarias y están sujetas a confirmación. Si cancela por medio de depósito o transferencia, esta debe ser por un monto mayor a $250 o su equivalente a moneda local (montos menores al indicado deben ser cancelados por otros medios disponibles) y necesitamos que nos envíe una copia del movimiento para su confirmación (este tiempo está sujeto a la recepción de la copia del movimiento). Este proceso tarda 48 horas hábiles para su aprobación por parte de Contabilidad. Hasta contar con esta aprobación se puede confirmar el inventario.');
