INSERT INTO club_texts (club_id, text_type, content) VALUES ((SELECT id FROM clubs WHERE club_number=8201), 'DELIVERY_DISCLAIMER', 'Prices are subject to change without notice, stocks depend on daily sales and are subject to confirmation.\n\nHome delivery:\nThis quote includes cost for transportation service also includes insurance on the merchandise.\n\n\nWith the approval of this quote and this clause I authorize the company Price Smart, on my behalf, to collect the merchandise I have purchased at PriceSmart Club 8201 Avenida Milio J. Croe #103 Oranjestad and that it will be delivered to my business.');
